alter table public.ai_operations add column claimed boolean not null default false;
create function public.claim_ai(p_operation uuid) returns boolean language plpgsql security definer set search_path='' as $$ declare claimed_id uuid;begin update public.ai_operations set claimed=true where id=p_operation and status='reserved' and not claimed returning id into claimed_id;return claimed_id is not null;end $$;
create function public.start_monitoring(p_user uuid,p_topic uuid) returns public.monitoring_runs language plpgsql security definer set search_path='' as $$ declare r public.monitoring_runs;begin perform pg_advisory_xact_lock(hashtextextended(p_user::text,2));if not exists(select 1 from public.topics where id=p_topic and user_id=p_user) then raise exception '主题不存在';end if;if exists(select 1 from public.monitoring_runs where user_id=p_user and created_at>now()-interval '1 minute') then raise exception '请等待一分钟后再次刷新';end if;if exists(select 1 from public.monitoring_runs where user_id=p_user and status='running' and created_at>now()-interval '2 minutes') then raise exception '已有采集任务运行中';end if;update public.monitoring_runs set status='failed',error='采集进程中断',finished_at=now() where user_id=p_user and status='running' and created_at<now()-interval '2 minutes';insert into public.monitoring_runs(user_id,topic_id) values(p_user,p_topic) returning * into r;return r;end $$;
revoke execute on function public.claim_ai(uuid),public.start_monitoring(uuid,uuid) from public,anon,authenticated;
grant execute on function public.claim_ai(uuid),public.start_monitoring(uuid,uuid) to service_role;
